import { ChevronDown, ChevronUp, IconProps } from '@hexa-ui/icons';
import React, {
  forwardRef,
  InputHTMLAttributes,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react';
import { useCombobox, UseComboboxState, UseComboboxStateChangeTypes } from 'downshift';
import { useVirtualizer } from '@tanstack/react-virtual';
import debounce from 'lodash.debounce';
import { Checkbox } from '../checkbox';

import {
  StyledCombobox,
  StyledPopover,
  StyledLabel,
  StyledArrowUpContainer,
  StyledArrowDownContainer,
  StyledHint,
  StyledErrorMessage,
  StyledInfoIcon,
  StyledScrollContainer,
  StyledWrapper,
  StyledListItem,
  StyledIconContainer,
  RelativeContainer,
  NoResultsParagraph,
} from './Combobox.styles';

export type ComboboxMultipleProps = Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'autoComplete' | 'size' | 'placeholder'
> & {
  label?: string;
  shape?: 'square' | 'pill';
  size?: 'small' | 'medium' | 'large';
  error?: string;
  hint?: string;
  icon?: React.FunctionComponent<IconProps>;
  disabled?: boolean;
  onSelectItems: (items?: string[]) => void;
  value?: string;
  options: string[];
  placeholder?: string;
  displayText?: string;
  width?: string | number;
};

type PopoverPositionStyle = {
  top: number | string;
  width: number | string;
};

export type ComboboxRef = {
  ref: HTMLInputElement;
  clearSelection: () => void;
};

const Combobox = forwardRef<ComboboxRef, ComboboxMultipleProps>(
  (
    {
      label,
      options,
      placeholder = 'Select a value',
      hint,
      shape = 'square',
      size = 'large',
      icon: Icon,
      error,
      disabled,
      displayText = 'items selected',
      width = '100%',
      onSelectItems,
      ...rest
    }: ComboboxMultipleProps,
    forwardedRef: React.ForwardedRef<ComboboxRef>
  ) => {
    const selectSizes = {
      small: 32,
      medium: 40,
      large: 48,
    };
    const [inputItems, setInputItems] = useState<string[]>(options);
    const [inputSearchItem, setInputSearchItem] = useState('');
    const [selectedItems, setSelectedItems] = useState<string[]>([]);
    const innerRef = useRef<HTMLInputElement>(null);
    const [popoverPosition, setPopoverPosition] = useState<PopoverPositionStyle>(() => ({
      top: selectSizes[size],
      width: '100%',
    }));
    const [popoverOptionsHeight, setPopoverOptionsHeight] = useState(() => ({
      height: 'min-height',
    }));
    const popoverRef = useRef<null | HTMLDivElement>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const [scrollToken, setScrollToken] = useState<NodeJS.Timer | null>(null);
    const [visibleArrows, setVisibleArrows] = useState({
      up: false,
      down: false,
    });

    const handleItemContainerScroll = (el: HTMLDivElement | (EventTarget & HTMLDivElement)) => {
      const scrollAtTheTop = el.scrollTop === 0;
      const scrollAtTheMiddle = el.scrollTop !== 0 && el.scrollTop !== el.clientHeight;
      const scrollAtTheBottom = Math.abs(el.scrollHeight - el.scrollTop - el.clientHeight) < 1;

      if (scrollAtTheBottom) {
        setVisibleArrows({ up: true, down: false });
        return;
      }
      if (scrollAtTheTop) {
        setVisibleArrows({ up: false, down: true });
        return;
      }
      if (scrollAtTheMiddle) {
        setVisibleArrows({ up: true, down: true });
      }
    };

    const handleArrowHover = (direction: 'up' | 'down') => () => {
      if (!visibleArrows.up && !visibleArrows.down) return;
      const scrollAmount = direction === 'up' ? -20 : 20;
      const scrollContainerEl = scrollContainerRef?.current;

      setScrollToken(
        setInterval(() => {
          if (scrollContainerEl) {
            scrollContainerEl.scrollBy({
              top: scrollAmount,
              behavior: 'smooth',
            });
            handleItemContainerScroll(scrollContainerEl);
          }
        }, 100)
      );
    };

    const onMouseLeaveArrowContainer = () => {
      if (scrollToken) clearInterval(scrollToken);
      setScrollToken(null);
    };

    const {
      isOpen,
      inputValue,
      getLabelProps,
      getMenuProps,
      getInputProps,
      getComboboxProps,
      getItemProps,
      getToggleButtonProps,
      openMenu,
      reset,
    } = useCombobox({
      items: inputItems,
      selectedItem: null,
      onSelectedItemChange: ({ selectedItem, type }) => {
        const selectionTypes: UseComboboxStateChangeTypes[] = [
          useCombobox.stateChangeTypes.ItemClick,
          useCombobox.stateChangeTypes.InputKeyDownEnter,
        ];
        if (selectedItem && selectionTypes.includes(type)) {
          if (!selectedItems.includes(selectedItem)) {
            setSelectedItems(selectedItems.concat(selectedItem));
          } else {
            setSelectedItems(
              selectedItems.filter(
                (selectedItemsItem: string) => selectedItem !== selectedItemsItem
              )
            );
          }
        }
      },
      stateReducer: (state, actionAndChanges): Partial<UseComboboxState<string>> => {
        const { changes, type } = actionAndChanges;
        switch (type) {
          case useCombobox.stateChangeTypes.InputChange:
            if (changes.inputValue) setInputSearchItem(changes.inputValue);
            return changes;
          case useCombobox.stateChangeTypes.InputKeyDownEnter:
          case useCombobox.stateChangeTypes.ItemClick:
            return {
              ...changes,
              isOpen: true,
              highlightedIndex: state.highlightedIndex,
              inputValue: inputSearchItem,
            };
          case useCombobox.stateChangeTypes.InputBlur:
            return { ...changes, isOpen: !!changes.selectedItem };
          default:
            return changes;
        }
      },
      onInputValueChange: (changes) => {
        setInputItems(
          options.filter(
            (optionItem) =>
              !changes.inputValue ||
              optionItem.toLowerCase().includes(changes.inputValue.toLowerCase())
          )
        );
      },
    });

    const rowVirtualizer = useVirtualizer({
      count: inputItems.length,
      getScrollElement: () => scrollContainerRef.current,
      estimateSize: () => 56,
      overscan: inputItems.length,
    });

    const handleClearSelection = () => {
      setSelectedItems([]);
      reset();
    };

    useImperativeHandle(
      forwardedRef,
      () =>
        ({
          ref: innerRef?.current,
          clearSelection: handleClearSelection,
        } as ComboboxRef)
    );

    const handleSelect = useCallback((items?: string[]) => onSelectItems(items), [onSelectItems]);

    const hasComboboxHeightPassingEndScreen = (
      comboboxSelBottom: number,
      popoverHeight: number,
      windowHeight: number
      // eslint-disable-next-line max-params
    ): boolean => comboboxSelBottom + popoverHeight >= windowHeight;

    const hasComboboxHeightPassingStartScreen = (
      distanceSelectOfWindowTop: number,
      comboboxSelectHeight: number
    ): boolean => distanceSelectOfWindowTop <= comboboxSelectHeight;

    const setComboboxOptionsContainerPosition = useCallback(
      () =>
        debounce(() => {
          const comboboxSelectSpacingOfPopover = 4;
          const comboboxPopoverArrowsHeight = 32;

          const selectEl: HTMLInputElement = innerRef?.current as HTMLInputElement;
          const popoverEl = popoverRef?.current;

          if (popoverEl && selectEl && isOpen) {
            const { bottom, top } = selectEl.getBoundingClientRect();

            const windowHeight = window.innerHeight;
            const distanceSelectOfWindowEnd = windowHeight - bottom;
            const distanceSelectOfWindowTop = top;
            const comboboxSelectHeight = selectEl.clientHeight;
            const comboboxSelectWidth = selectEl.clientWidth;

            let newPopoverOptionsHeight = 'max-content';
            let positionTop = selectEl.clientHeight + comboboxSelectSpacingOfPopover;
            if (hasComboboxHeightPassingEndScreen(bottom, popoverEl.clientHeight, windowHeight)) {
              if (distanceSelectOfWindowEnd >= 200)
                newPopoverOptionsHeight = `${
                  distanceSelectOfWindowEnd -
                  comboboxSelectSpacingOfPopover -
                  comboboxPopoverArrowsHeight
                }px`;
              else
                positionTop = -(
                  comboboxSelectHeight +
                  popoverEl.clientHeight +
                  comboboxSelectSpacingOfPopover
                );
            } else if (
              hasComboboxHeightPassingStartScreen(distanceSelectOfWindowTop, comboboxSelectHeight)
            ) {
              newPopoverOptionsHeight = `${
                distanceSelectOfWindowTop -
                comboboxSelectSpacingOfPopover -
                comboboxPopoverArrowsHeight
              }px`;
            }

            setPopoverOptionsHeight({
              height: newPopoverOptionsHeight,
            });
            setPopoverPosition({
              top: positionTop,
              width: comboboxSelectWidth,
            });
          }
        })(),
      [popoverRef, isOpen]
    );

    useEffect(() => {
      window.addEventListener('scroll', () => setComboboxOptionsContainerPosition());
      window.addEventListener('resize', () => setComboboxOptionsContainerPosition());
      return () => {
        window.removeEventListener('scroll', () => setComboboxOptionsContainerPosition());
        window.removeEventListener('resize', () => setComboboxOptionsContainerPosition());
      };
    }, [setComboboxOptionsContainerPosition]);

    useEffect(() => {
      const scrollContainerEl = scrollContainerRef?.current;
      if (scrollContainerEl && isOpen) {
        const hasScroll = scrollContainerEl.scrollHeight > scrollContainerEl.clientHeight;
        if (hasScroll) setVisibleArrows({ up: false, down: true });
        else setVisibleArrows({ up: false, down: false });
        setComboboxOptionsContainerPosition();
      }
    }, [scrollContainerRef, setComboboxOptionsContainerPosition, isOpen]);

    useEffect(() => {
      handleSelect(selectedItems);
    }, [selectedItems, handleSelect]);

    const inputPlaceholder = () => {
      if (!selectedItems.length || selectedItems.length === 0) return placeholder;
      if (selectedItems.length === 1) {
        return selectedItems[0];
      }
      return `${selectedItems.length} ${displayText}`;
    };

    return (
      <>
        {label && (
          <StyledLabel
            className="label"
            disabled={disabled}
            error={Boolean(error)}
            {...getLabelProps()}
          >
            {label}
          </StyledLabel>
        )}
        {error && (
          <StyledErrorMessage>
            <StyledInfoIcon size="tiny" />
            {error}
          </StyledErrorMessage>
        )}
        {hint && <StyledHint>{hint}</StyledHint>}
        <RelativeContainer>
          <StyledCombobox
            css={{ width }}
            ref={innerRef}
            shape={shape}
            size={size}
            disabled={disabled}
            {...getComboboxProps({ ref: innerRef })}
            {...rest}
          >
            {Icon && <Icon size="medium" />}
            <input
              {...getInputProps({ placeholder: inputPlaceholder() })}
              onClick={() => openMenu()}
              disabled={disabled}
            />
            {isOpen ? (
              <StyledIconContainer {...getToggleButtonProps()}>
                <ChevronUp size="medium" />
              </StyledIconContainer>
            ) : (
              <StyledIconContainer {...getToggleButtonProps()}>
                <ChevronDown size="medium" />
              </StyledIconContainer>
            )}
          </StyledCombobox>
          <StyledPopover {...getMenuProps({ ref: popoverRef })} style={{ ...popoverPosition }}>
            {isOpen && (
              <div>
                <StyledArrowUpContainer
                  onMouseEnter={handleArrowHover('up')}
                  onMouseLeave={onMouseLeaveArrowContainer}
                  visible={visibleArrows.up}
                >
                  <ChevronUp size="medium" />
                </StyledArrowUpContainer>
                {(!rowVirtualizer.getVirtualItems() ||
                  rowVirtualizer.getVirtualItems().length === 0) && (
                  <NoResultsParagraph alignment="center">{`No results found for ${inputValue}`}</NoResultsParagraph>
                )}

                {rowVirtualizer.getVirtualItems() && (
                  <StyledScrollContainer
                    style={{ ...popoverOptionsHeight }}
                    onScroll={(e) => {
                      handleItemContainerScroll(e.currentTarget);
                    }}
                    ref={scrollContainerRef}
                  >
                    <StyledWrapper
                      style={{
                        height: `${rowVirtualizer.getTotalSize()}px`,
                        width: '100%',
                        position: 'relative',
                      }}
                    >
                      {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                      {rowVirtualizer.getVirtualItems().map((virtualizedItem: any) => (
                        <StyledListItem
                          key={virtualizedItem.index}
                          {...getItemProps({ item: virtualizedItem, index: virtualizedItem.index })}
                        >
                          <Checkbox
                            id={virtualizedItem.index}
                            label={inputItems[virtualizedItem.index]}
                            value={inputItems[virtualizedItem.index]}
                            checked={selectedItems?.includes(inputItems[virtualizedItem.index])}
                          />
                        </StyledListItem>
                      ))}
                    </StyledWrapper>
                  </StyledScrollContainer>
                )}
                <StyledArrowDownContainer
                  onMouseEnter={handleArrowHover('down')}
                  onMouseLeave={onMouseLeaveArrowContainer}
                  visible={visibleArrows.down}
                >
                  <ChevronDown size="medium" />
                </StyledArrowDownContainer>
              </div>
            )}
          </StyledPopover>
        </RelativeContainer>
      </>
    );
  }
);

export default Combobox;
